import{_ as t,o,c as n,a2 as a}from"./chunks/framework.CdjpmwdR.js";const h=JSON.parse('{"title":"DevContainer in Practice: Reproducible Dev Environments","description":"Practical guidance for DevContainer in multi-language projects—defining, building, connecting, and sharing containers to reduce local drift and version conflicts.","frontmatter":{"category":"node","date":"2023-12-01","title":"DevContainer in Practice: Reproducible Dev Environments","description":"Practical guidance for DevContainer in multi-language projects—defining, building, connecting, and sharing containers to reduce local drift and version conflicts.","tags":["node","IaC","Go","Java","devx"],"image":"https://pic1.zhimg.com/v2-09afb8c8e561f75d874bde41efa327c0_r.jpg"},"headers":[],"relativePath":"en/blogs/2023/202312-devcontainer-tutorial.md","filePath":"en/blogs/2023/202312-devcontainer-tutorial.md"}'),i={name:"en/blogs/2023/202312-devcontainer-tutorial.md"};function r(c,e,s,l,d,p){return o(),n("div",null,[...e[0]||(e[0]=[a('<p><img src="https://pic1.zhimg.com/v2-09afb8c8e561f75d874bde41efa327c0_r.jpg" alt=""></p><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>With multiple languages and projects in parallel, local environments go out of control easily. Even with directory conventions and version managers, toolchain conflicts keep piling up.</p><p>Some tools are installed via <code>curl</code> plus their own <code>upgrade</code> commands, some via <code>brew</code>. Project A needs Terraform 1.3.5, project B still wants 1.2.0. On top of that, Java is managed via <code>asdf-vm</code>, Go via <code>gvm</code>, Node via <code>nvm</code> – each with different mental models.</p><p>On Windows (WSL), I revisited DevContainer and gradually turned common projects into dedicated dev containers: <strong>on‑demand, isolated, easy to rebuild</strong>.</p><p>Reference: <a href="https://code.visualstudio.com/docs/devcontainers/containers" target="_blank" rel="noreferrer">Developing inside a Container using Visual Studio Code Remote Development</a></p><h2 id="define" tabindex="-1">Define <a class="header-anchor" href="#define" aria-label="Permalink to &quot;Define&quot;">​</a></h2><p><img src="https://pic1.zhimg.com/80/v2-0b47d65b53aa9c6db6fef23f2c031afc_1440w.webp" alt=""></p><p>DevContainer uses JSON to describe the dev environment. The key pieces:</p><ul><li><code>image</code>: base container image – see <a href="https://containers.dev/templates" target="_blank" rel="noreferrer">containers.dev: Templates</a><ul><li>Official templates exist for many languages and stacks</li><li>You can also build your own (with a VS Code server preinstalled)</li></ul></li><li><code>features</code>: scripts and tools to install – see <a href="https://containers.dev/features" target="_blank" rel="noreferrer">containers.dev: Features</a><ul><li>The spec defines a standard interface for features, so you can easily publish your own</li><li>Features can be shipped as OCI artifacts in registries</li></ul></li></ul><h2 id="build-start" tabindex="-1">Build &amp; Start <a class="header-anchor" href="#build-start" aria-label="Permalink to &quot;Build &amp; Start&quot;">​</a></h2><p><img src="https://pic4.zhimg.com/80/v2-5664ed72bbb8f58fcd1cc0fa78d5b747_1440w.webp" alt=""></p><p>You can use the VS Code command <strong>Create Dev Container</strong> to set things up, or you can write <code>.devcontainer/devcontainer.json</code> yourself. When you open the project, VS Code will detect it and offer to <strong>Reopen in Dev Container</strong>.</p><p>When you confirm, DevContainer (CLI) builds a new image and starts the matching container.</p><p>Patterns that work well:</p><ul><li>Split images by language, frontend/backend or project</li><li>Containers don’t affect each other</li><li>If the container is missing a tool, either: <ul><li>Edit <code>devcontainer.json</code> and reload, or</li><li>Install ad‑hoc inside the container</li></ul></li></ul><p>If you need databases or middleware, you can bring them up with <strong>docker‑compose</strong>.</p><blockquote><p>See: <a href="https://code.visualstudio.com/docs/devcontainers/create-dev-container#_use-docker-compose" target="_blank" rel="noreferrer">Create a development container using Visual Studio Code Remote Development</a></p></blockquote><h2 id="connect" tabindex="-1">Connect <a class="header-anchor" href="#connect" aria-label="Permalink to &quot;Connect&quot;">​</a></h2><p><img src="https://pic2.zhimg.com/80/v2-fe602d2918e1baec9423793ff9c23f75_1440w.webp" alt=""></p><p>VS Code then connects to the server running inside the container via the DevContainer extension. From that point on, you’re editing files <strong>in the container</strong>.</p><p>You can either:</p><ul><li>Mount your local project into the container as a volume, or</li><li><code>git clone</code> directly inside the container</li></ul><p>On macOS and Windows, Docker runs in a VM, so heavy volume mounts can be slow. In that case I prefer cloning directly inside the container.</p><p>(The downside: other tools on the host can’t edit the same files.)</p><blockquote><p><em>&quot;Enjoy your Dev Environments&quot;</em></p></blockquote><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>You can share dev environments with others via <code>devcontainer.json</code> or even exported images</li><li>GitHub Codespaces uses the same config, so you can take the same setup to the cloud</li><li>Extensions installed <strong>inside</strong> the dev container are scoped to that container and won’t pollute your global VS Code</li><li>With Profiles you can separate shortcuts and VS Code settings further, if you care</li><li>You can run multiple dev containers at the same time</li></ul><p><img src="https://pic2.zhimg.com/80/v2-8f372319fa1a9464e462ddd6534a7f99_1440w.webp" alt=""></p><ul><li>A single dev container can host multiple projects: <ul><li>Use the Command Palette to create a dev container <strong>or</strong> a starter project</li><li>Configure <code>devcontainer.json</code>, then Reopen in Container</li><li>Once inside, <code>mkdir</code> and <code>git clone</code> new repos</li><li>Use <strong>Open Folder</strong> for each project</li><li>Later you can use <strong>Open Recent</strong> to jump back directly into projects inside the container</li></ul></li></ul><p><img src="https://pic3.zhimg.com/80/v2-1959b48b01e08f0eb60d68a2259c27b2_1440w.webp" alt=""></p><p><img src="https://pic2.zhimg.com/v2-2868526299016bfd589152ce101c29d1_b.png" alt=""></p><p><img src="https://pic2.zhimg.com/80/v2-2868526299016bfd589152ce101c29d1_1440w.webp" alt=""></p><h2 id="closing" tabindex="-1">Closing <a class="header-anchor" href="#closing" aria-label="Permalink to &quot;Closing&quot;">​</a></h2><p>From both imagination and execution, VS Code is far ahead of most IDEs – and Microsoft/GitHub’s ecosystem makes it even stronger. With Copilot / ChatGPT in the loop, VS Code as the &quot;default universe IDE&quot; is basically a done deal.</p><p>For large companies, dev containers and remote coding are not just toys:</p><ul><li>Better dev experience</li><li>Centralized control over source code and secrets</li><li>Potentially <strong>lower total cost</strong> than buying every engineer a maxed‑out laptop.</li></ul>',37)])])}const m=t(i,[["render",r]]);export{h as __pageData,m as default};
